import {reposFinderPath} from '@github-ui/paths'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import type {ReposFilterProps} from '@github-ui/repos-filter'
import type {SidebarLink} from '@github-ui/repos-list'
import {getShortcutsWithSaved, useShortcutDeletion, useShortcutEditor} from '@github-ui/repos-list'
import {useSearchParams} from '@github-ui/use-navigate'
import {useListResults} from '@github-ui/use-repos-list-results'
import {useState} from 'react'

import {getItemFromQuery} from '../components/FinderSidebar'
import type {PagePayload} from '../types'
import {useFinderDefinitions} from './use-finder-definitions'

const DEFAULT_FILTER_VALUE = 'contributed-by:@me'

function useFinderListResults(payload: PagePayload, page: number | undefined) {
  return useListResults(payload, reposFinderPath(), page, DEFAULT_FILTER_VALUE)
}

/**
 * Hook to manage the state of the repos finder page, including query state,
 * repository shortcuts, and sidebar selection. Provides methods for updating
 * and submitting queries, managing shortcuts, and selecting sidebar links.
 *
 * @param payload The page payload containing initial data such as repo shortcuts and suggested orgs.
 * @returns An object containing the current query, fetched query, shortcuts, selected sidebar item,
 *          editing and deleting shortcut states, list results, current page, fetching status,
 *          methods for updating and submitting queries, selecting sidebar links, creating and editing shortcuts,
 *          and props for the repository filter component.
 */
export function useReposFinderState(payload: PagePayload) {
  const [params] = useSearchParams()

  const [fetchedQuery, setFetchedQuery] = useState(params.get('q') || DEFAULT_FILTER_VALUE)
  const [query, setQuery] = useState(fetchedQuery)

  const {results, currentPage, isFetching, fetchResults} = useFinderListResults(payload, Number(params.get('page')))

  async function submitQuery(q: string) {
    await fetchResults({q, page: 1})
    setFetchedQuery(q)
  }

  const [shortcuts, setShortcuts] = useState(
    () => payload.repoShortcuts?.map(shortcut => ({...shortcut, searchType: 'repositories'}) as SidebarLink) || [],
  )

  const [selectedSidebarItem, setSelectedSidebarItem] = useState<SidebarLink | undefined>(() =>
    getItemFromQuery(query, shortcuts),
  )

  const onShortcutDeleted = (deletedShortcut: SidebarLink) => {
    setShortcuts(shortcuts.filter(shortcut => shortcut.id !== deletedShortcut.id))
    setSelectedSidebarItem(undefined)
  }
  const deleting = useShortcutDeletion(onShortcutDeleted)

  const onShortcutSaved = (savedShortcut: SidebarLink) => {
    setShortcuts(getShortcutsWithSaved(shortcuts, savedShortcut))
    setSelectedSidebarItem(savedShortcut)

    if (fetchedQuery !== savedShortcut.query) {
      submitQuery(savedShortcut.query)
    }
  }
  const editing = useShortcutEditor(onShortcutSaved)

  const {orgsDefinitions, updateDefinitionsForOrgs} = useFinderDefinitions()

  const showFilterDialog = useFeatureFlag('repos_list_show_filter_dialog')
  const showOrgsDefinitions = useFeatureFlag('repos_finder_suggest_properties')

  function updateQuery(q: string) {
    setQuery(q)
    if (editing.shortcut) {
      editing.setValue('query', q)
    }
    if (showOrgsDefinitions) {
      updateDefinitionsForOrgs(q)
    }
  }

  function updateAndSubmitQuery(q: string) {
    updateQuery(q)
    submitQuery(q)
  }

  async function kindlyDismissEditing() {
    if (editing.shortcut) {
      const dismissed = await editing.dismiss()
      if (!dismissed) return false
    }
    return true
  }

  async function selectSidebarLink(linkItem: SidebarLink) {
    if (!(await kindlyDismissEditing())) return
    deleting.reset()

    setSelectedSidebarItem(linkItem)
    setQuery(linkItem.query)
    if (showOrgsDefinitions) {
      updateDefinitionsForOrgs(linkItem.query)
    }
    submitQuery(linkItem.query)
  }

  async function createShortcut() {
    if (!(await kindlyDismissEditing())) return

    setSelectedSidebarItem(undefined)
    deleting.reset()
    editing.create(query, selectedSidebarItem)
  }

  function editShortcut(shortcut: SidebarLink) {
    deleting.reset()
    editing.edit(shortcut, query)
  }

  const reposFilterProps: ReposFilterProps = {
    options: {withOwnerTerms: true, withFinderTerms: true, withRelevanceSort: true},
    id: 'repos-finder-filter',
    label: 'Search repositories',
    variant: showFilterDialog ? 'full' : 'input',
    placeholder: 'Search repositories',
    filterValue: query,
    orgs: payload.suggestedOrgs,
    definitions: orgsDefinitions,
    onChange: updateQuery,
    onSubmit: filterQuery => submitQuery(filterQuery.raw),
  }

  return {
    query,
    fetchedQuery,
    shortcuts,
    selectedSidebarItem,
    editing,
    deleting,
    results,
    currentPage,
    isFetching,
    methods: {
      updateAndSubmitQuery,
      selectSidebarLink,
      createShortcut,
      editShortcut,
      fetchResults,
    },
    reposFilterProps,
  }
}
