interface FinderSidebarProps {
  type: string
  onSelectLink: (linkItem: SidebarLink) => void
}

export function FinderSidebar({type, onSelectLink}: FinderSidebarProps) {
  return <ListSidebar links={useSidebarLinks()} selectedLink={type} onSelectLink={onSelectLink} />
}

interface FinderSidebarCollapsedButtonProps extends FinderSidebarProps {
  shortcuts: SidebarLink[]
  onCreateView: () => void
}

export function FinderSidebarCollapsedButton({
  type,
  onSelectLink,
  shortcuts,
  onCreateView,
}: FinderSidebarCollapsedButtonProps) {
  const showReposShortcuts = useFeatureFlag('repos_finder_shortcuts')

  const allLinks = [...useSidebarLinks(), ...shortcuts]

  return (
    <ListSidebarCollapsedButton
      links={allLinks}
      selectedLink={type}
      onSelectLink={onSelectLink}
      showCreateShortcuts={showReposShortcuts}
      onCreateView={onCreateView}
    />
  )
}

export function getItemFromQuery(query: string, shortcuts: SidebarLink[]) {
  const allUserLinks = [...sidebarLinks, ...shortcuts]
  return allUserLinks.find(item => item.query === query.trim())
}

function useSidebarLinks() {
  const showInternalPrivate = useFeatureFlag('repos_finder_unbounded')
  if (showInternalPrivate) {
    return sidebarLinks
  }

  return sidebarLinks.filter(link => !['internal', 'private'].includes(link.id))
}

try{ FinderSidebar.displayName ||= 'FinderSidebar' } catch {}
