import {newRepoPath} from '@github-ui/paths'
import {ReposFilter, type ReposFilterProps} from '@github-ui/repos-filter'
import type {SidebarLink} from '@github-ui/repos-list'
import {Button, Flash, Truncate} from '@primer/react'

import styles from './FinderHeader.module.css'
import {FinderSidebarCollapsedButton} from './FinderSidebar'
import {ShortcutOptionsButton} from './ShortcutOptionsButton'

interface FinderHeaderProps {
  selectedSidebarItem: SidebarLink | undefined
  reposFilterProps: ReposFilterProps
  shortcuts: SidebarLink[]
  onSelectLink: (linkItem: SidebarLink) => void
  onCreateView: () => void
  onEditView: (shortcut: SidebarLink) => void
  onDeleteView: (shortcut: SidebarLink) => void
  deleteErrorMessage?: string
}

export function FinderHeader({
  selectedSidebarItem,
  reposFilterProps,
  shortcuts,
  onSelectLink,
  onCreateView,
  onEditView,
  onDeleteView,
  deleteErrorMessage,
}: FinderHeaderProps) {
  const {name = 'Search', description} = selectedSidebarItem || {}
  return (
    <div>
      {deleteErrorMessage && (
        <Flash variant="danger" className="mb-3">
          {deleteErrorMessage}
        </Flash>
      )}
      <div className="d-flex flex-wrap flex-md-nowrap gap-2 mb-3">
        <div className="flex-1 min-width-0">
          <div className="d-flex flex-items-top gap-2">
            <div className="hide-lg hide-xl">
              <FinderSidebarCollapsedButton
                type={selectedSidebarItem?.id || ''}
                onSelectLink={onSelectLink}
                shortcuts={shortcuts}
                onCreateView={onCreateView}
              />
            </div>
            <h1 className="h3 hide-sm hide-md min-width-0" data-testid="finder-header-title">
              <Truncate title={name} maxWidth="100%">
                {name}
              </Truncate>
            </h1>
            {selectedSidebarItem?.source === 'user' && (
              <ShortcutOptionsButton
                onEditView={() => onEditView(selectedSidebarItem)}
                onDeleteView={() => onDeleteView(selectedSidebarItem)}
              />
            )}
          </div>
          {description && (
            <Truncate className={styles.description} title={description} maxWidth="100%">
              {description}
            </Truncate>
          )}
        </div>
        <Button as="a" href={newRepoPath()} variant="primary" size="medium">
          New repository
        </Button>
      </div>
      <ReposFilter {...reposFilterProps} />
    </div>
  )
}

try{ FinderHeader.displayName ||= 'FinderHeader' } catch {}