import {tokenizeQuery} from '@github-ui/filter-query'
import {reposPropertiesPath} from '@github-ui/paths'
import type {PropertyDefinition} from '@github-ui/repos-filter'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useState} from 'react'

export function useFinderDefinitions() {
  const [filterOrgs, setFilterOrgs] = useState<string[]>([])
  const [orgsDefinitions, setOrgsDefinitions] = useState<PropertyDefinition[]>([])

  async function updateDefinitionsForOrgs(query: string) {
    const tokenizedQuery = tokenizeQuery(query)
    const orgFilters = tokenizedQuery.filter(seg => seg.type === 'filter').filter(seg => seg.key === 'org')

    const hasNegatedOrgFilter = orgFilters.some(filter => filter.isNegated === true)
    if (!orgFilters.length || hasNegatedOrgFilter) {
      setFilterOrgs([])
      setOrgsDefinitions([])
      return
    }

    const newFilterOrgs = orgFilters.flatMap(filter => filter.values).toSorted()
    if (equalArrays(newFilterOrgs, filterOrgs)) {
      return
    }

    setFilterOrgs(newFilterOrgs)
    setOrgsDefinitions([])

    const response = await verifiedFetchJSON(reposPropertiesPath({orgs: newFilterOrgs}))
    if (!response.ok) {
      return
    }

    const serializedResponse = (await response.json()) as {definitions: PropertyDefinition[]}
    setOrgsDefinitions(serializedResponse.definitions)
  }

  return {orgsDefinitions, updateDefinitionsForOrgs}
}

function equalArrays(arr1: string[], arr2: string[]) {
  if (arr1.length !== arr2.length) {
    return false
  }

  return arr1.every((value, index) => value === arr2[index])
}
