import {AnalyticsProvider} from '@github-ui/analytics-provider'
import {ContextualGlobalSsoBanner} from '@github-ui/global-sso-banner'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {
  addSortToQuery,
  getSortFromQuery,
  ReposList,
  ReposShortcutSidebar,
  sortingOptionsWithRelevance,
  useCompactModeSetting,
} from '@github-ui/repos-list'
import {NoReposBlankslate} from '@github-ui/repos-list-blankslate'
import {PageLayout, Pagination} from '@primer/react'

import {FinderHeader} from '../components/FinderHeader'
import {FinderSidebar} from '../components/FinderSidebar'
import {ShortcutEditingHeader} from '../components/ShortcutEditingHeader'
import {useFinderScreenReaderAnnouncements} from '../hooks/use-finder-screen-reader-announcements'
import {useReposFinderState} from '../hooks/use-repos-finder-state'
import type {PagePayload} from '../types'
import {reposFinderPageRoute} from './repos-finder-page-route'

const DEFAULT_SORTING_KEY = 'relevance'

export function ReposFinderDataRouterPage() {
  const {data: payload} = useRouteQuery(reposFinderPageRoute, 'mainQuery')

  return (
    <AnalyticsProvider appName="repos-finder-page" category="Finder page" metadata={{page: 'repos-finder'}}>
      <ContextualGlobalSsoBanner />
      <ReposFinderPage payload={payload} />
    </AnalyticsProvider>
  )
}

export function ReposFinderPage({payload}: {payload: PagePayload}) {
  const {
    query,
    fetchedQuery,
    shortcuts,
    selectedSidebarItem,
    editing,
    deleting,
    results,
    currentPage,
    isFetching,
    methods,
    reposFilterProps,
  } = useReposFinderState(payload)

  const showReposShortcuts = useFeatureFlag('repos_finder_shortcuts')
  const {updateCompactModeSetting} = useCompactModeSetting(payload.compactMode, 'repos_finder_compact_mode')

  const {emptyMessages} = useFinderScreenReaderAnnouncements(
    isFetching,
    currentPage,
    fetchedQuery,
    results,
    DEFAULT_SORTING_KEY,
  )

  return (
    <PageLayout containerWidth="full" columnGap="none" padding="none">
      <PageLayout.Pane
        divider="line"
        hidden={{narrow: true, regular: false, wide: false}}
        padding="condensed"
        position="start"
      >
        <aside>
          <FinderSidebar type={selectedSidebarItem?.id || ''} onSelectLink={methods.selectSidebarLink} />
          {showReposShortcuts && (
            <ReposShortcutSidebar
              shortcuts={shortcuts}
              onSelectLink={methods.selectSidebarLink}
              selectedLink={selectedSidebarItem?.id || ''}
              onCreateView={methods.createShortcut}
            />
          )}
        </aside>
      </PageLayout.Pane>

      <PageLayout.Content padding="condensed" className="min-height-full px-2 mx-auto" style={{maxWidth: '1400px'}}>
        {editing.shortcut ? (
          <ShortcutEditingHeader
            reposFilterProps={reposFilterProps}
            onSave={editing.saveAndDismiss}
            onDismiss={editing.dismiss}
            shortcut={editing.shortcut}
            setShortcutValue={editing.setValue}
            isSaving={editing.isSaving}
            errorMessage={editing.errorMessage}
          />
        ) : (
          <FinderHeader
            selectedSidebarItem={selectedSidebarItem}
            reposFilterProps={reposFilterProps}
            shortcuts={shortcuts}
            onSelectLink={methods.selectSidebarLink}
            onCreateView={methods.createShortcut}
            onDeleteView={deleting.deleteShortcut}
            onEditView={methods.editShortcut}
            deleteErrorMessage={deleting.errorMessage}
          />
        )}
        <div className="my-3">
          <div data-hpc>
            <ReposList
              query={fetchedQuery}
              showNameWithOwner
              compactMode={payload.compactMode}
              onCompactModeChanged={updateCompactModeSetting}
              showSpinner={isFetching}
              repositoryCount={results.repositoryCount}
              repos={results.repositories}
              onSortingItemSelect={sort => methods.updateAndSubmitQuery(addSortToQuery(query, sort))}
              sortingItemSelected={getSortFromQuery(query)}
              defaultSortingKey={DEFAULT_SORTING_KEY}
              sortingOptions={sortingOptionsWithRelevance}
              directionRestrictedKeys={{nonAscending: ['relevance']}}
              noReposMessage={<NoReposBlankslate message={emptyMessages} />}
            />
          </div>
        </div>
        {results.pageCount > 1 && (
          <Pagination
            pageCount={results.pageCount}
            currentPage={currentPage}
            onPageChange={(e, page) => {
              // Avoid adding hash parameters
              e.preventDefault()

              window.scrollTo({top: 0})
              methods.fetchResults({q: query, page})
            }}
          />
        )}
      </PageLayout.Content>
    </PageLayout>
  )
}

try{ ReposFinderDataRouterPage.displayName ||= 'ReposFinderDataRouterPage' } catch {}
try{ ReposFinderPage.displayName ||= 'ReposFinderPage' } catch {}