import type {ReposFilterProps} from '@github-ui/repos-filter'
import {ReposFilter} from '@github-ui/repos-filter'
import type {EditableShortcutField, UserShortcut} from '@github-ui/repos-list'
import {isValidShortcutName, isValidShortcutQuery} from '@github-ui/repos-list'
import {Button, Flash, FormControl, TextInput} from '@primer/react'
import {useRef, useState} from 'react'

import {IconAndColorPicker} from './IconAndColorPicker'

interface ShortcutEditingHeaderProps {
  reposFilterProps: ReposFilterProps
  onDismiss: () => void
  onSave: () => void
  shortcut: UserShortcut
  setShortcutValue: (fieldName: EditableShortcutField, value: string) => void
  isSaving?: boolean
  errorMessage?: string
}

export function ShortcutEditingHeader({
  reposFilterProps,
  onDismiss,
  onSave,
  shortcut,
  setShortcutValue,
  isSaving = false,
  errorMessage,
}: ShortcutEditingHeaderProps) {
  const titleRef = useRef<HTMLInputElement>(null)
  const filterRef = useRef<HTMLInputElement>(null)

  const [hasInteractedWithTitle, setHasInteractedWithTitle] = useState(false)

  function onSaveButtonClick() {
    if (!shortcut) throw new Error('Editing shortcut is undefined while submitting.')

    if (!isValidShortcutName(shortcut)) {
      setHasInteractedWithTitle(true)
      titleRef.current?.focus()
      return
    }

    if (!isValidShortcutQuery(shortcut)) {
      filterRef.current?.focus()
      return
    }

    onSave()
  }

  return (
    <form className="d-flex flex-column gap-2">
      {errorMessage && <Flash variant="danger">{errorMessage}</Flash>}
      <div className="d-flex flex-items-start gap-2">
        <FormControl>
          <FormControl.Label>Icon</FormControl.Label>
          <IconAndColorPicker
            selectedColor={shortcut.color}
            selectedIcon={shortcut.icon}
            onApply={(color, icon) => {
              setShortcutValue('color', color)
              setShortcutValue('icon', icon)
            }}
          />
        </FormControl>
        <FormControl required className="flex-grow-1 width-full">
          <FormControl.Label>Title</FormControl.Label>
          <TextInput
            autoFocus
            ref={titleRef}
            className="width-full"
            placeholder="Title"
            value={shortcut.name}
            onChange={({target}) => {
              setHasInteractedWithTitle(true)
              setShortcutValue('name', target.value)
            }}
          />
          {!isValidShortcutName(shortcut) && hasInteractedWithTitle && (
            <FormControl.Validation variant="error">Title can not be empty</FormControl.Validation>
          )}
        </FormControl>
      </div>

      <FormControl>
        <FormControl.Label>Description</FormControl.Label>
        <TextInput
          className="width-full"
          placeholder="Add a description"
          value={shortcut.description}
          onChange={({target}) => setShortcutValue('description', target.value)}
        />
      </FormControl>

      <FormControl required>
        <FormControl.Label>Query</FormControl.Label>
        <div className="d-flex flex-items-start gap-2 width-full flex-wrap flex-lg-nowrap">
          <div className="d-flex flex-column gap-1 width-full">
            <ReposFilter {...reposFilterProps} inputRef={filterRef} className="width-full" />
            {!isValidShortcutQuery(shortcut) && (
              <FormControl.Validation variant="error">Query can not be empty</FormControl.Validation>
            )}
          </div>
          <Button type="button" onClick={onDismiss} disabled={isSaving}>
            Cancel
          </Button>
          <Button type="button" variant="primary" onClick={onSaveButtonClick} disabled={isSaving}>
            {isSaving ? 'Saving...' : 'Save view'}
          </Button>
        </div>
      </FormControl>
    </form>
  )
}

try{ ShortcutEditingHeader.displayName ||= 'ShortcutEditingHeader' } catch {}